/**
 * Pieces for the two Screen index pages (Prototypes › iPhone app / Crane Web › Screen index).
 * Rows come from `screen-index-data.ts`, generated by `scripts/gen-screen-index.mjs`.
 */
import { DOC, DocLink, DocTable, Pill, iphonePrototype, webPrototype } from "../docs-kit/docs-kit";
import type { ScreenIndexRow } from "./screen-index-data";

export interface AreaGroup {
    name: string;
    count: number;
    /** First story of the area, in sidebar order. */
    firstId: string;
}

/** Areas (top-level folders) in sidebar order, with story counts. */
export const groupsOf = (rows: ScreenIndexRow[]): AreaGroup[] => {
    const out: AreaGroup[] = [];
    for (const r of rows) {
        const g = out.find((x) => x.name === r.group);
        if (g) g.count++;
        else out.push({ name: r.group, count: 1, firstId: r.id });
    }
    return out;
};

const groupOf = (rows: ScreenIndexRow[], name: string) => {
    const g = groupsOf(rows).find((x) => x.name === name);
    if (!g) throw new Error(`Screen index: no area "${name}"`);
    return g;
};

/** Number of stories in an area. */
export const countIn = (rows: ScreenIndexRow[], name: string) => groupOf(rows, name).count;

/** Id of an area's first story (for "Stories →" links). */
export const firstIdIn = (rows: ScreenIndexRow[], name: string) => groupOf(rows, name).firstId;

/** "N · AREA · X STORIES" eyebrow for an area card. */
export const areaEyebrow = (rows: ScreenIndexRow[], n: number, name: string, label = name) => {
    const c = countIn(rows, name);
    return `${n} · ${label} · ${c} ${c === 1 ? "story" : "stories"}`;
};

/** Total pill plus one pill per area with its count. */
export const AreaPills = ({ rows }: { rows: ScreenIndexRow[] }) => (
    <>
        <Pill tone="brand">{rows.length} stories</Pill>
        {groupsOf(rows).map((g) => (
            <Pill key={g.name}>
                {g.name}
                <span style={{ color: DOC.muted, marginLeft: 6, fontWeight: 500 }}>{g.count}</span>
            </Pill>
        ))}
    </>
);

/** The table: #, Area, Screen (name + one line), Open (story, and prototype when it has a route). */
export const ScreenIndexTable = ({ rows, prototype }: { rows: ScreenIndexRow[]; prototype: "web" | "iphone" }) => (
    <DocTable
        columns={["#", "Area", "Screen", "Open"]}
        widths={[52, 230, "auto", 150]}
        rows={rows.map((r, i) => {
            const [group, ...rest] = r.area.split(" · ");
            return [
                <span key="n" style={{ color: DOC.muted, fontVariantNumeric: "tabular-nums" }}>
                    {i + 1}
                </span>,
                <span key="a" className="flex flex-col">
                    <span style={{ color: DOC.ink, fontWeight: 600 }}>{group}</span>
                    {rest.length > 0 && <span style={{ color: DOC.muted }}>{rest.join(" · ")}</span>}
                </span>,
                <span key="s" className="flex flex-col gap-0.5">
                    <strong style={{ color: DOC.ink }}>{r.name}</strong>
                    <span>{r.description}</span>
                </span>,
                <span key="o" className="flex flex-col items-start gap-1">
                    <DocLink to={r.id}>Story</DocLink>
                    {r.path && <DocLink href={prototype === "web" ? webPrototype(r.path) : iphonePrototype(r.path)}>Prototype</DocLink>}
                </span>,
            ];
        })}
    />
);
